const clean=v=>String(v??'').trim();
const usable=v=>{const t=clean(v);return (!t||t==='?'||t==='-')?'':t};
const validName=x=>{const n=clean(x?.name);return !!n&&!['LIDERES','LÍDERES','LIDER','LÍDER'].includes(n.toUpperCase())};
const safePolling=v=>{const t=usable(v);if(!t)return '';const low=t.toLowerCase();if(low.includes('campaña')||low.includes('trabajar con')||low.includes('es de '))return '';return t};
const validCedula=v=>{const t=usable(v).replace(/\D/g,'');return t.length>=5?t:''};
const esc=s=>clean(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const sectors=[...new Set(BASE.map(x=>x.sector).filter(Boolean))];
function currentDB(){return window.db||db}
function save(){try{saveDB()}catch(_){localStorage.setItem('matriz_giron_v1',JSON.stringify(currentDB()));try{renderAll()}catch(e){}}}
function matchesExisting(x){const d=currentDB();const ced=validCedula(x.cedula);const name=clean(x.name).toLowerCase(),barrio=clean(x.barrio).toLowerCase();return d.leaders.find(l=>(ced&&validCedula(l.cedula)===ced)||(!ced&&clean(l.name).toLowerCase()===name&&clean(l.territory||l.barrio).toLowerCase()===barrio))}
function importLeader(x,opts={}){if(!validName(x))return null;let found=matchesExisting(x);const ced=validCedula(x.cedula),phone=usable(x.phone),polling=safePolling(x.pollingPlace);if(found){found.communicationsConsent='Sí';if(!clean(found.sectorTerritorial))found.sectorTerritorial=clean(x.sector);if(!clean(found.operationalSector))found.operationalSector=clean(x.operationalSector);if(!clean(found.groupTerritorial))found.groupTerritorial=clean(x.group);if(!clean(found.barrio))found.barrio=clean(x.barrio);if(!clean(found.territory))found.territory=clean(x.barrio);if(!clean(found.vereda))found.vereda='GIRÓN - ÁREA URBANA';if(!clean(found.cedula)&&ced)found.cedula=ced;if(!clean(found.address)&&usable(x.address))found.address=usable(x.address);if(!clean(found.phone)&&phone)found.phone=phone;if(!clean(found.whatsapp)&&phone)found.whatsapp=phone;if(!clean(found.pollingPlace)&&polling)found.pollingPlace=polling;if(!clean(found.preferredChannel))found.preferredChannel='WhatsApp';if(!clean(found.notes))found.notes='Importado desde Base Territorial de Girón';if(!opts.deferSave)save();return found}const l={id:'L'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),name:clean(x.name),cedula:ced,role:'Líder territorial',organization:'',territory:clean(x.barrio),vereda:'GIRÓN - ÁREA URBANA',sectorTerritorial:clean(x.sector),operationalSector:clean(x.operationalSector),groupTerritorial:clean(x.group),barrio:clean(x.barrio),address:usable(x.address),phone,whatsapp:phone,email:'',birthDate:'',pollingPlace:polling,communicationsConsent:'Sí',lastCommunication:'',preferredChannel:'WhatsApp',notes:'Importado desde Base Territorial de Girón · autorización de comunicaciones confirmada por el responsable de la base',created:new Date().toISOString()};currentDB().leaders.push(l);if(!opts.deferSave)save();return l}
function preloadAuthorizedLeaders(){const d=currentDB();if(!d||!Array.isArray(d.leaders))return;let touched=0;BASE.filter(validName).forEach(x=>{const before=matchesExisting(x);const prevConsent=before?.communicationsConsent;const prevCount=d.leaders.length;const l=importLeader(x,{deferSave:true});if(l&&(d.leaders.length!==prevCount||prevConsent!=='Sí'))touched++});if(touched){save()}try{localStorage.setItem('matriz_giron_base_territorial_preload_v1331',new Date().toISOString())}catch(_){}}
function fillForm(x){const f=document.getElementById('leaderForm');if(!f)return;const set=(n,v)=>{if(f.elements[n])f.elements[n].value=v||''};set('name',x.name);set('cedula',validCedula(x.cedula));set('role','Líder territorial');set('territory',x.barrio);set('vereda','GIRÓN - ÁREA URBANA');set('sectorTerritorial',x.sector);set('barrio',x.barrio);set('address',usable(x.address));set('phone',usable(x.phone));set('whatsapp',usable(x.phone));set('pollingPlace',safePolling(x.pollingPlace));set('communicationsConsent','Sí');set('preferredChannel','WhatsApp')}
function addFields(){const f=document.getElementById('leaderForm');if(!f||f.querySelector('[name=sectorTerritorial]'))return;const territory=f.querySelector('[name=territory]')?.closest('label');if(!territory)return;territory.insertAdjacentHTML('beforebegin',`<label>Sector territorial<input name="sectorTerritorial" readonly placeholder="Se completa desde la base territorial"></label><label>Barrio<input name="barrio" placeholder="Barrio / sector urbano"></label>`);const phone=f.querySelector('[name=phone]')?.closest('label');if(phone)phone.insertAdjacentHTML('beforebegin',`<label class="span-2">Dirección / referencia territorial<input name="address"></label><label class="span-2">Puesto de votación<input name="pollingPlace" placeholder="Dato territorial de referencia"></label>`);f.insertAdjacentHTML('afterbegin',`<section class="span-2 territorial-picker"><div><strong>📥 Cargar desde Base Territorial de Girón</strong><p>Seleccione sector, barrio y líder. Se copiarán únicamente datos objetivos de territorio y contacto.</p></div><div class="territorial-picker-grid"><select id="baseSector"><option value="">Sector</option></select><select id="baseBarrio"><option value="">Barrio</option></select><select id="baseLeader"><option value="">Líder</option></select><button type="button" class="secondary" id="baseLoadLeader">Usar datos</button></div></section>`);setupPicker()}
function setupPicker(){const s=document.getElementById('baseSector'),b=document.getElementById('baseBarrio'),l=document.getElementById('baseLeader'),btn=document.getElementById('baseLoadLeader');if(!s)return;s.innerHTML='<option value="">Sector</option>'+sectors.map(v=>`<option>${esc(v)}</option>`).join('');const refreshB=()=>{const bs=[...new Set(BASE.filter(x=>!s.value||x.sector===s.value).map(x=>x.barrio).filter(Boolean))];b.innerHTML='<option value="">Barrio</option>'+bs.map(v=>`<option>${esc(v)}</option>`).join('');refreshL()};const refreshL=()=>{const rows=BASE.filter(x=>(!s.value||x.sector===s.value)&&(!b.value||x.barrio===b.value));l.innerHTML='<option value="">Líder</option>'+rows.map(x=>`<option value="${BASE.indexOf(x)}">${esc(x.name)}</option>`).join('')};s.onchange=refreshB;b.onchange=refreshL;btn.onclick=()=>{const x=BASE[Number(l.value)];if(!x){alert('Seleccione un líder de la base territorial.');return}fillForm(x)};refreshB()}
function addQuickSelector(selectId,label){const target=document.getElementById(selectId);if(!target||target.closest('label')?.previousElementSibling?.classList?.contains('base-quick'))return;const wrap=document.createElement('div');wrap.className='base-quick span-2';wrap.innerHTML=`<strong>📥 Líder desde Base Territorial</strong><div class="base-quick-row"><select class="bq-sector"><option value="">Sector</option>${sectors.map(v=>`<option>${esc(v)}</option>`).join('')}</select><select class="bq-barrio"><option value="">Barrio</option></select><select class="bq-leader"><option value="">Líder</option></select><button type="button" class="secondary">Incorporar y usar</button></div><small>Los líderes de esta base se incorporan como contactos operativos con autorización de comunicaciones registrada en Sí.</small>`;target.closest('label').insertAdjacentElement('beforebegin',wrap);const s=wrap.querySelector('.bq-sector'),b=wrap.querySelector('.bq-barrio'),l=wrap.querySelector('.bq-leader');const rb=()=>{const vals=[...new Set(BASE.filter(x=>!s.value||x.sector===s.value).map(x=>x.barrio).filter(Boolean))];b.innerHTML='<option value="">Barrio</option>'+vals.map(v=>`<option>${esc(v)}</option>`).join('');rl()};const rl=()=>{const rows=BASE.filter(x=>(!s.value||x.sector===s.value)&&(!b.value||x.barrio===b.value));l.innerHTML='<option value="">Líder</option>'+rows.map(x=>`<option value="${BASE.indexOf(x)}">${esc(x.name)}</option>`).join('')};s.onchange=rb;b.onchange=rl;wrap.querySelector('button').onclick=()=>{const x=BASE[Number(l.value)];if(!x){alert('Seleccione un líder.');return}const leader=importLeader(x);if(!leader)return;if(selectId==='communityLeader'&&!leader.contactType){leader.contactType='Líder';save()}try{renderAll()}catch(_){};setTimeout(()=>{const sel=document.getElementById(selectId);if(sel)sel.value=leader.id},0)};rb()}
function enhanceTable(){const table=document.getElementById('leadersTable');if(!table)return;const observer=new MutationObserver(()=>{table.querySelectorAll('tbody tr').forEach(tr=>{const edit=tr.querySelector('button[onclick^="editLeader"]');if(!edit)return;const m=edit.getAttribute('onclick').match(/'([^']+)'/);const l=currentDB().leaders.find(x=>x.id===m?.[1]);if(!l||tr.dataset.territorial==='1')return;tr.dataset.territorial='1';const td=tr.children[3];if(td&&(l.sectorTerritorial||l.barrio||l.pollingPlace))td.innerHTML+=`<div class="territorial-mini">${esc(l.sectorTerritorial||'')}${l.barrio?'<br>'+esc(l.barrio):''}${l.pollingPlace?'<br>🗳️ '+esc(l.pollingPlace):''}</div>`})});observer.observe(table,{childList:true,subtree:true})}
window.MatrizBaseTerritorial={records:BASE,leaderRecords:BASE.filter(validName),importLeader,preloadAuthorizedLeaders};
preloadAuthorizedLeaders();addFields();addQuickSelector('communityLeader');enhanceTable();
